import { agent, s, workflow } from "rig";
import { readFileSync } from "node:fs";

type Pr = { number: number; title: string; body?: string; labels?: unknown[]; url?: string; html_url?: string };

// Agent role: judge whether two PRs address the same engineering concern.
const judgePair = agent({
  name: "judgePair",
  model: "small",
  input: s.object({ a: s.string, b: s.string }),
  output: s.object({ same: s.boolean }),
  instructions:
    "Given two PR descriptions, answer same=true only if they address the same specific engineering concern or subsystem change (not merely the same repo).",
});

// Agent role: name and summarize a cluster of PRs.
const describeCluster = agent({
  name: "describeCluster",
  model: "small",
  input: s.object({ titles: s.array(s.string) }),
  output: s.object({ label: s.string, summary: s.string }),
  instructions: "Give a short thematic label (max 6 words) and a one-sentence evidence-grounded summary for these PR titles.",
});

const STOP = new Set("the a an and or of to for in on with add fix update from by is be as at this that into new use using via rig".split(" "));
const tokens = (t: string) =>
  new Set(t.toLowerCase().replace(/\[[^\]]*\]/g, " ").split(/[^a-z0-9]+/).filter((w) => w.length > 2 && !STOP.has(w)));
const jaccard = (x: Set<string>, y: Set<string>) => {
  let i = 0;
  for (const w of x) if (y.has(w)) i++;
  return x.size + y.size - i === 0 ? 0 : i / (x.size + y.size - i);
};

// Workflow role: cluster merged PRs by title-token candidate edges confirmed by pairwise model judgments, then connected components.
export default workflow({
  meta: {
    name: "pairwise-verified-graph-components",
    description: "Candidate edges from title-token Jaccard, verified by model, connected components as clusters",
    phases: ["Candidates", "Verify", "Describe"],
  },
  body: async ({ call, phase, pipeline }) => {
    const corpus = JSON.parse(readFileSync("/tmp/gh-aw/agent/merged-prs.json", "utf8"));
    const prs: Pr[] = corpus.prs;
    const nums = new Set(prs.map((p) => p.number));
    if (nums.size !== prs.length || prs.length === 0) throw new Error("bad corpus");
    const toks = new Map(prs.map((p) => [p.number, tokens(p.title)]));
    const brief = (p: Pr) => `${p.title}\n${(p.body ?? "").replace(/https?:\S+/g, "").replace(/\s+/g, " ").slice(0, 250)}`;

    phase("Candidates");
    const cand: { a: Pr; b: Pr; j: number }[] = [];
    for (let i = 0; i < prs.length; i++)
      for (let k = i + 1; k < prs.length; k++) {
        const j = jaccard(toks.get(prs[i].number)!, toks.get(prs[k].number)!);
        if (j >= 0.2) cand.push({ a: prs[i], b: prs[k], j });
      }
    cand.sort((x, y) => y.j - x.j || x.a.number - y.a.number || x.b.number - y.b.number);
    const picked = cand.slice(0, 30);

    phase("Verify");
    const verdicts = await pipeline(picked, (c) =>
      call(judgePair, { a: brief(c.a), b: brief(c.b) }, { label: `${c.a.number}-${c.b.number}` }));
    const parent = new Map<number, number>(prs.map((p) => [p.number, p.number]));
    const find = (x: number): number => (parent.get(x) === x ? x : (parent.set(x, find(parent.get(x)!)), parent.get(x)!));
    let missing = 0;
    verdicts.forEach((v, i) => {
      if (!v || typeof v.same !== "boolean") { missing++; return; }
      if (v.same) parent.set(find(picked[i].a.number), find(picked[i].b.number));
    });
    if (missing > 0) throw new Error(`${missing} missing judge responses`);

    const groups = new Map<number, number[]>();
    for (const p of prs) {
      const r = find(p.number);
      groups.set(r, [...(groups.get(r) ?? []), p.number]);
    }
    const multi = [...groups.values()].filter((g) => g.length >= 2).map((g) => g.sort((x, y) => x - y));
    const unclassified = [...groups.values()]
      .filter((g) => g.length < 2)
      .map((g) => ({ pr: g[0], reason: "No verified same-concern link to any other PR (singleton component)" }))
      .sort((x, y) => x.pr - y.pr);
    const byNum = new Map(prs.map((p) => [p.number, p]));

    phase("Describe");
    const described = await pipeline(multi.slice(0, 25), (g) =>
      call(describeCluster, { titles: g.map((n) => byNum.get(n)!.title) }, { label: `c${g[0]}` }));
    if (described.some((d) => !d || !d.label || !d.summary)) throw new Error("missing cluster description");
    const clusters = multi
      .slice(0, 25)
      .map((g, i) => ({ id: `c${String(g[0]).padStart(5, "0")}`, label: described[i]!.label, summary: described[i]!.summary, prs: g, size: g.length }))
      .sort((x, y) => y.size - x.size || x.id.localeCompare(y.id));
    if (multi.length > 25) throw new Error("too many clusters");

    const seen = new Set<number>();
    for (const n of [...clusters.flatMap((c) => c.prs), ...unclassified.map((u) => u.pr)]) {
      if (!nums.has(n) || seen.has(n)) throw new Error(`invalid or duplicate PR ${n}`);
      seen.add(n);
    }
    if (seen.size !== prs.length) throw new Error("incomplete coverage");
    if (new Set(clusters.map((c) => c.id)).size !== clusters.length) throw new Error("duplicate cluster id");

    return {
      repository: corpus.repository,
      window: corpus.window,
      strategy: "Pairwise-verified similarity graph: Jaccard title-token candidate edges, model-verified, connected components",
      totalPrs: prs.length,
      modelCalls: picked.length + clusters.length,
      clusters,
      topThree: clusters.slice(0, 3).map((c) => c.id),
      unclassified,
    };
  },
});
